using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;

namespace ShipmentTracker.Data;

public class ApplicationDbContext(DbContextOptions<ApplicationDbContext> options) : IdentityDbContext<ApplicationUser>(options)
{
    public DbSet<Shipment> Shipments => Set<Shipment>();

    protected override void OnModelCreating(ModelBuilder builder)
    {
        base.OnModelCreating(builder);

        builder.Entity<Shipment>()
            .HasIndex(s => s.TrackingNumber)
            .IsUnique();

        builder.Entity<IdentityRole>().HasData(
            new IdentityRole { Id = "dispatcher-role", Name = "Dispatcher", NormalizedName = "DISPATCHER" },
            new IdentityRole { Id = "customer-role", Name = "Customer", NormalizedName = "CUSTOMER" }
        );

        var now = new DateTime(2026, 6, 1, 0, 0, 0, DateTimeKind.Utc);
        builder.Entity<Shipment>().HasData(
            new Shipment { Id = 1, TrackingNumber = "TRK-100001", Origin = "New York, US", Destination = "London, UK", Status = ShipmentStatus.InTransit, ShippedDate = now.AddDays(-3), EstimatedDelivery = now.AddDays(4), RecipientName = "Alice Johnson", Description = "Electronics - 2 boxes", WeightKg = 12.5 },
            new Shipment { Id = 2, TrackingNumber = "TRK-100002", Origin = "Shanghai, CN", Destination = "Los Angeles, US", Status = ShipmentStatus.Pending, ShippedDate = now.AddDays(-1), EstimatedDelivery = now.AddDays(12), RecipientName = "Bob Smith", Description = "Furniture parts", WeightKg = 85.0 },
