using Microsoft.AspNetCore.Authorization;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Data;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments");

        group.MapGet("/", [Authorize] async (ApplicationDbContext db) =>
        {
            var shipments = await db.Shipments
                .OrderByDescending(s => s.ShippedDate)
                .Select(s => MapToDto(s))
                .ToListAsync();
            return Results.Ok(shipments);
        });

        group.MapGet("/track/{trackingNumber}", [Authorize] async (string trackingNumber, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments
                .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
            if (shipment is null)
                return Results.NotFound();
            return Results.Ok(MapToDto(shipment));
        });

        group.MapPut("/{id}/status", [Authorize(Roles = "Dispatcher")] async (int id, UpdateShipmentStatusRequest request, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null)
                return Results.NotFound();

            shipment.Status = (Data.ShipmentStatus)(int)request.Status;
            if (request.Status == Client.Models.ShipmentStatus.Delivered)
                shipment.ActualDelivery = DateTime.UtcNow;

            await db.SaveChangesAsync();
            return Results.Ok(MapToDto(shipment));
        });
    }

    private static ShipmentDto MapToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = (Client.Models.ShipmentStatus)(int)s.Status,
        ShippedDate = s.ShippedDate,
        EstimatedDelivery = s.EstimatedDelivery,
        ActualDelivery = s.ActualDelivery,
        RecipientName = s.RecipientName,
        Description = s.Description,
        WeightKg = s.WeightKg
    };
}

@page "/dispatcher"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Microsoft.AspNetCore.Authorization.Authorize(Roles = "Dispatcher")]
@rendermode InteractiveAuto

<PageTitle>Dispatcher Dashboard</PageTitle>

<h1>📦 Dispatcher Dashboard</h1>

<div class="row mb-3">
    <div class="col-md-4">
        <input type="text" class="form-control" placeholder="Search by tracking #, destination, or recipient..."
               @bind="searchTerm" @bind:event="oninput" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="statusFilter">
            <option value="">All Statuses</option>
            @foreach (var status in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@status">@status</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button class="btn btn-primary w-100" @onclick="LoadShipments">
            🔄 Refresh
        </button>
    </div>
</div>

@if (loading)
{
    <p><em>Loading shipments...</em></p>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger">@errorMessage</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th @onclick='() => SetSort("TrackingNumber")' style="cursor:pointer">
                        Tracking # @SortIndicator("TrackingNumber")
                    </th>
                    <th @onclick='() => SetSort("Origin")' style="cursor:pointer">
                        Origin @SortIndicator("Origin")
                    </th>
                    <th @onclick='() => SetSort("Destination")' style="cursor:pointer">
                        Destination @SortIndicator("Destination")
                    </th>
                    <th @onclick='() => SetSort("Status")' style="cursor:pointer">
                        Status @SortIndicator("Status")
                    </th>
                    <th>Recipient</th>
                    <th @onclick='() => SetSort("EstimatedDelivery")' style="cursor:pointer">
                        Est. Delivery @SortIndicator("EstimatedDelivery")
                    </th>
                    <th>Weight (kg)</th>
                    <th>Actions</th>
                </tr>
