@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Microsoft.AspNetCore.Authorization.Authorize]
@rendermode InteractiveAuto

<PageTitle>Track Shipment</PageTitle>

<h1>🔍 Track Your Shipment</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control form-control-lg" placeholder="Enter tracking number (e.g. TRK-100001)"
                   @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary btn-lg" @onclick="Search" disabled="@searching">
                @if (searching)
                {
                    <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                }
                Track
            </button>
        </div>
    </div>
</div>

@if (notFound)
{
    <div class="alert alert-warning">
        <strong>Not found.</strong> No shipment matches tracking number <em>"@searchedNumber"</em>.
        Please double-check and try again.
    </div>
}
else if (shipment is not null)
{
    <div class="card shadow-sm">
        <div class="card-header d-flex justify-content-between align-items-center">
            <h4 class="mb-0">@shipment.TrackingNumber</h4>
            <span class="badge fs-6 @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <h5>Shipment Details</h5>
                    <dl class="row">
                        <dt class="col-sm-5">Description</dt>
                        <dd class="col-sm-7">@shipment.Description</dd>

                        <dt class="col-sm-5">Weight</dt>
                        <dd class="col-sm-7">@shipment.WeightKg.ToString("F1") kg</dd>

                        <dt class="col-sm-5">Recipient</dt>
                        <dd class="col-sm-7">@shipment.RecipientName</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <h5>Route &amp; Schedule</h5>
                    <dl class="row">
                        <dt class="col-sm-5">Origin</dt>
                        <dd class="col-sm-7">@shipment.Origin</dd>

                        <dt class="col-sm-5">Destination</dt>
                        <dd class="col-sm-7">@shipment.Destination</dd>

                        <dt class="col-sm-5">Shipped</dt>
                        <dd class="col-sm-7">@shipment.ShippedDate.ToString("MMM dd, yyyy")</dd>

                        <dt class="col-sm-5">Est. Delivery</dt>
                        <dd class="col-sm-7">
                            <strong>@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</strong>
                            @if (shipment.Status != ShipmentStatus.Delivered && shipment.Status != ShipmentStatus.Cancelled)
                            {
                                var daysLeft = (shipment.EstimatedDelivery.Date - DateTime.UtcNow.Date).Days;
                                if (daysLeft > 0)
                                {
                                    <span class="text-muted"> (@daysLeft day@(daysLeft != 1 ? "s" : "") away)</span>
                                }
                                else if (daysLeft == 0)
                                {
                                    <span class="text-success"> (Today!)</span>
                                }
                                else
                                {
                                    <span class="text-danger"> (@Math.Abs(daysLeft) day@(Math.Abs(daysLeft) != 1 ? "s" : "") overdue)</span>
                                }
                            }
                        </dd>

                        @if (shipment.ActualDelivery.HasValue)
                        {
                            <dt class="col-sm-5">Delivered On</dt>
                            <dd class="col-sm-7 text-success">
                                <strong>@shipment.ActualDelivery.Value.ToString("MMM dd, yyyy")</strong>
                            </dd>
                        }
                    </dl>
                </div>
            </div>

            <hr />
            <h5>Shipment Progress</h5>
            @{
                var steps = new[] {
                    ShipmentStatus.Pending,
                    ShipmentStatus.PickedUp,
                    ShipmentStatus.InTransit,
                    ShipmentStatus.OutForDelivery,
                    ShipmentStatus.Delivered
                };
                var currentStep = Array.IndexOf(steps, shipment.Status);
            }

            @if (shipment.Status == ShipmentStatus.Cancelled)
            {
                <div class="alert alert-dark">This shipment has been <strong>cancelled</strong>.</div>
            }
            else if (shipment.Status == ShipmentStatus.Delayed)
            {
                <div class="alert alert-danger">This shipment is currently <strong>delayed</strong>. We're working to resolve the issue.</div>
            }
            else
            {
                <div class="d-flex justify-content-between position-relative mt-3 mb-4">
                    @for (int i = 0; i < steps.Length; i++)
                    {
                        var step = steps[i];
                        var isCompleted = i <= currentStep;
                        var isCurrent = i == currentStep;
                        <div class="text-center flex-fill">
                            <div class="rounded-circle d-inline-flex align-items-center justify-content-center @(isCompleted ? "bg-success" : "bg-secondary")"
                                 style="width:36px;height:36px;@(isCurrent ? "box-shadow: 0 0 0 3px rgba(25,135,84,.4);" : "")">
                                <span class="text-white small">@(isCompleted ? "✓" : (i + 1).ToString())</span>
                            </div>
                            <div class="small mt-1 @(isCurrent ? "fw-bold" : "")">@step</div>
                        </div>
                    }
                </div>
            }
        </div>
    </div>
}

